// --- CONFIGURATION ---
u_min := 0;
u_max := 6.28318; 
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- SHADER CODE ---

// Base parameters
float scale = 3.0; 
float r = 0.4;

// Slider A controls the "4D lift"
// We use directly the "A" variable injected by the program
float lift4D = A * 3.0; 

// --- 1. CENTRAL CURVE (Figure-8) ---
// We use different frequencies for W to avoid collisions
vec4 Curve4D = vec4(
    (2.5 + cos(2.0 * u)) * cos(3.0 * u), // X
    (2.5 + cos(2.0 * u)) * sin(3.0 * u), // Y
    1.2 * sin(4.0 * u),                  // Z (creates the crossing in 3D)
    lift4D * sin(2.0 * u)                // W (separates the crossing in 4D)
);

// Extract the 3D part for the classic vector math
vec3 Curve = Curve4D.xyz;

// --- 2. DERIVATIVE (velocity) ---
// Compute the 3D tangent to build the tube correctly
float dr = -2.0 * sin(2.0 * u);
vec3 dC = vec3(
    dr * cos(3.0 * u) - (2.5 + cos(2.0 * u)) * 3.0 * sin(3.0 * u),
    dr * sin(3.0 * u) + (2.5 + cos(2.0 * u)) * 3.0 * cos(3.0 * u),
    4.8 * cos(4.0 * u)
);
vec3 Tangent = normalize(dC);

// --- 3. STABLE FRAME (Global Up) ---
// Use Z as the up vector to avoid pinching
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = cross(Tangent, Up);
if (length(Binorm) < 0.001) Binorm = cross(Tangent, vec3(0.0, 1.0, 0.0));
Binorm = normalize(Binorm);
vec3 Norm = cross(Binorm, Tangent);
Norm = normalize(Norm);

// --- 4. TUBE CONSTRUCTION ---
float tube_cos = r * cos(v);
float tube_sin = r * sin(v);

// The final position has the 3D tube coordinates + the curve's W coordinate
vec3 pos3D = Curve + (tube_cos * Norm + tube_sin * Binorm);

// 4D output: (X, Y, Z, W)
// W depends on slider A. If you move A, the node shifts in 4D and "opens up".
return vec4(pos3D * 0.35, Curve4D.w);
